BEGIN;
CREATE TABLE ad_project_runtime_policy(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,project_id text NOT NULL,policy_version text NOT NULL,project_root text NOT NULL,allowed_paths jsonb NOT NULL,blocked_paths jsonb NOT NULL,allowed_commands jsonb NOT NULL,blocked_commands jsonb NOT NULL,max_runtime_seconds integer NOT NULL,max_attempts integer NOT NULL,allow_commit boolean NOT NULL DEFAULT false,allow_push boolean NOT NULL DEFAULT false CHECK(allow_push=false),allow_merge boolean NOT NULL DEFAULT false CHECK(allow_merge=false),allow_deploy boolean NOT NULL DEFAULT false CHECK(allow_deploy=false),status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,workspace_id,project_id,policy_version));
CREATE TABLE ad_runtime_approval(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,project_id text NOT NULL,goal_id uuid NOT NULL REFERENCES ad_goal(id),task_id uuid NOT NULL REFERENCES ad_task(id),runtime_type text NOT NULL,worker_id uuid NOT NULL REFERENCES ad_worker(id),policy_version text NOT NULL,status text NOT NULL,requested_by text NOT NULL,reviewed_by text,expires_at timestamptz NOT NULL,max_uses integer NOT NULL DEFAULT 1 CHECK(max_uses>0),used_count integer NOT NULL DEFAULT 0 CHECK(used_count<=max_uses),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,consumed_at timestamptz,revoked_at timestamptz);
CREATE TABLE ad_credential_reference_binding(id uuid PRIMARY KEY,organization_id text NOT NULL,workspace_id text NOT NULL,project_id text NOT NULL,runtime_type text NOT NULL,credential_reference_id text NOT NULL,reference_type text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,workspace_id,project_id,runtime_type),CHECK(credential_reference_id !~* '(token|password|secret|api[_-]?key)='));
CREATE TABLE ad_outbox_consumption(consumer_name text NOT NULL,event_id uuid NOT NULL REFERENCES ad_outbox_event(event_id),consumed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(consumer_name,event_id));
CREATE TABLE ad_session_projection(session_id uuid PRIMARY KEY REFERENCES ad_night_shift_session(id),session_status text NOT NULL,goal_status text,worker_status jsonb NOT NULL DEFAULT '{}',blocking_reasons jsonb NOT NULL DEFAULT '[]',morning_report jsonb NOT NULL DEFAULT '{}',last_event_id uuid,last_projected_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ad_approval_lookup ON ad_runtime_approval(organization_id,workspace_id,project_id,task_id,runtime_type,worker_id,status,expires_at);
COMMIT;
